import { action } from "solid-js";
const act = () => { void action(function* () {})(); };
const some = Uint32Array.prototype.some;
document.addEventListener("click", (event) => {
  event.view.Uint32Array.prototype.some = function (...args) {
    act();
    return some.apply(this, args);
  };
}, { once: true });
document.documentElement.click();
